//! Unsealed full ACTION data over genuine original raw-policy page loans.
use crate::{captured_generator_budget::Budget,captured_reactive_reads::Failure,reactive_raw_policy_pages::RawPolicyPages,sparse_slots_policy::Output,actions_policy::Builder,key_policy_control::Control};
use std::{collections::{BTreeMap,HashMap},io,sync::Arc};
struct Scratch{budget:Arc<Budget>,ok:bool}impl Drop for Scratch{fn drop(&mut self){if !self.ok{self.budget.keep_failed_scratch()}}}
fn oom(budget:&Budget,message:impl Into<String>)->Failure{budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message.into()))}
fn check(budget:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{budget.require().map_err(|m|oom(budget,m))?;poll()?;budget.require().map_err(|m|oom(budget,m))}
struct Native<'a>{budget:&'a Budget,poll:&'a dyn Fn()->io::Result<()>}impl Control for Native<'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{check(self.budget,self.poll)}fn reserve(&mut self,n:usize)->Result<(),Failure>{self.budget.charge(n).map_err(|m|oom(self.budget,m))}fn overflow(&mut self)->Failure{oom(self.budget,"Actions scanner admission overflow")}fn allocation_failed(&mut self)->Failure{self.overflow()}}
fn retained(out:&Output)->Option<usize>{out.diags.iter().try_fold(out.body.capacity().checked_add(out.diags.capacity().checked_mul(std::mem::size_of::<crate::sparse_slots_policy::Diagnostic>())?)?,|n,d|n.checked_add(d.rel.capacity())?.checked_add(d.msg.capacity()))}
/// Unsealed original ACTION data, with exact requested notice/field membership.
pub fn generate_from_pages(pages:&dyn RawPolicyPages,order:&HashMap<String,usize>,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<Output,Failure>{
 check(root,poll)?;let mut scratch=Scratch{budget:Budget::scoped_temporaries(root).map_err(|m|oom(root,m))?,ok:false};let budget=&scratch.budget;
 let result=(||{
 let rows=crate::reactive_raw_policy_pages::collect_marker_rows(|visit|pages.for_each(visit),order,budget,&["ACTION"],false,false,false,&mut||check(budget,poll).map_err(|e|match e{Failure::Operational(e)=>e,Failure::Unsupported(m)=>io::Error::other(m)}),&||check(budget,poll))?;
 let mut builder=Builder::captured(Arc::clone(budget));for marker in &rows.markers{check(budget,poll)?;builder.push(&marker.rel,marker.line,&marker.args).map_err(|message|if budget.denied(){oom(budget,message)}else{Failure::Unsupported(message)})?;check(budget,poll)?;}let prepared=builder.prepare_with(||check(budget,poll))?;
 let mut requested:BTreeMap<String,BTreeMap<String,bool>>=BTreeMap::new();for(notice,var)in prepared.requests(){check(budget,poll)?;if !requested.get(notice).is_some_and(|vars|vars.contains_key(var)){budget.charge(notice.len().checked_add(var.len()).and_then(|n|n.checked_mul(2)).and_then(|n|n.checked_add(4096)).ok_or_else(||oom(budget,"Actions membership directory overflow"))?).map_err(|m|oom(budget,m))?;requested.entry(notice.to_owned()).or_default().insert(var.to_owned(),false);}}
 budget.charge(requested.keys().try_fold(256usize,|n,key|n.checked_add(key.len().checked_mul(2)?)?.checked_add(4*std::mem::size_of::<String>())).ok_or_else(||oom(budget,"Actions notice selector overflow"))?).map_err(|m|oom(budget,m))?;let names:Vec<String>=requested.keys().cloned().collect();
 if !names.is_empty(){let complete=pages.for_each(&mut|relative,views|{let budget=views.allocation_budget(budget);check(budget,poll)?;if relative=="code/engine/_generated/actions.dm"{return Ok(true)}let code=views.code()?;let cap=names.len().checked_mul(4).and_then(|n|n.checked_add(4)).ok_or_else(||oom(budget,"Actions notice selection overflow"))?;budget.charge(cap).map_err(|m|oom(budget,m))?;let mut selected=Vec::new();selected.try_reserve_exact(names.len()).map_err(|e|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,e)))?;if selected.capacity()>cap{return Err(oom(budget,"Actions notice allocator exceeded admission"))}for name in &names{check(budget,poll)?;selected.push(crate::actions_policy::file_mentions_notice(&code.text,name));}if !selected.iter().any(|yes|*yes){return Ok(true)}let clean=views.clean(budget)?;let mut control=Native{budget,poll};crate::raw_type_vars_policy::visit_with(clean,&mut control,&mut|ty,var|{if let Ok(at)=names.binary_search_by(|name|name.as_str().cmp(ty)){if selected[at]{if let Some(found)=requested.get_mut(ty).and_then(|vars|vars.get_mut(var)){*found=true}}}Ok(())})?;Ok(true)})?;if !complete{return Err("Actions membership traversal stopped before exhaustion".into())}}
 let mut output=prepared.finish_with(|notice,var|requested.get(notice).and_then(|vars|vars.get(var)).copied().unwrap_or(false),||check(budget,poll))?;check(budget,poll)?;root.charge(retained(&output).ok_or_else(||oom(root,"Actions output capacity overflow"))?).map_err(|m|oom(root,m))?;let mut owned=Output::default();owned.body=std::mem::take(&mut output.body);owned.diags=std::mem::take(&mut output.diags);drop(output);Ok(owned)
 })();let result=match result{Err(Failure::Operational(actual))=>Err(Failure::Operational(actual)),other if budget.denied()=>{drop(other);Err(oom(budget,"Actions operation denied"))},other=>{check(budget,poll)?;other}};scratch.ok=result.is_ok();drop(scratch);if matches!(&result,Err(Failure::Operational(_))){return result}check(root,poll)?;result
}

#[cfg(test)]#[path="actions_policy_frozen_original.rs"]mod original_actions;
#[cfg(test)]mod tests{use super::*;use super::original_actions as original;use crate::captured_raw_file::{File,RawPolicyViews};use std::cell::Cell;
struct Pages{files:Vec<File>,fail:Cell<bool>,stop:Cell<bool>}impl RawPolicyPages for Pages{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{for file in &self.files{if !file.with_policy_views(visit)?{return Ok(false)}}if self.fail.get(){return Err(Failure::Operational(io::Error::from_raw_os_error(1450)))}Ok(!self.stop.get())}}
fn fixture()->Pages{let root=std::env::current_dir().unwrap().join("actions-page-data");let text="ACTION(hit, num/power)\nACTION(hit/child, num/extra)\nACTION(query_move, QUERY, mob/mover)\nACTION(bad, num/holder)\n/datum/notice/hit\n    var/power\n";Pages{files:vec![File::capture(&root,&root.join("code/a.dm"),text.to_owned().into()).unwrap()],fail:Cell::new(false),stop:Cell::new(false)}}
#[test]fn actions_pages_match_complete_frozen_original_output_and_all_ordered_diagnostics(){let pages=fixture();let budget=Budget::new(16*1024*1024).unwrap();let before=budget.used();let output=generate_from_pages(&pages,&HashMap::new(),&budget,&||Ok(())).unwrap();assert_eq!(budget.used()-before,retained(&output).unwrap()+std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>(),"only funded output and existing fixed scratch metadata may remain");let mut old=original::Builder::default();for(line,args)in [(1,vec!["hit","num/power"]),(2,vec!["hit/child","num/extra"]),(3,vec!["query_move","QUERY","mob/mover"]),(4,vec!["bad","num/holder"]) ]{old.push("code/a.dm",line,&args.into_iter().map(str::to_owned).collect::<Vec<_>>()).unwrap();}let old=old.prepare(||Ok(())).unwrap().finish(|notice,name|notice=="/datum/notice/hit"&&name=="power",||Ok(())).unwrap();assert_eq!(output.body,old.body);assert_eq!(output.diags,old.diags);assert!(!output.diags.is_empty());assert!(output.body.contains("/proc/query_query_move"));}
#[test]fn actions_pages_preserve_actual_io_stopped_and_quota_before_later_cancel_then_recover(){let pages=fixture();pages.fail.set(true);assert!(matches!(generate_from_pages(&pages,&HashMap::new(),&Budget::new(16*1024*1024).unwrap(),&||Ok(())),Err(Failure::Operational(ref error))if error.raw_os_error()==Some(1450)));pages.fail.set(false);pages.stop.set(true);assert!(matches!(generate_from_pages(&pages,&HashMap::new(),&Budget::new(16*1024*1024).unwrap(),&||Ok(())),Err(Failure::Unsupported(_))));pages.stop.set(false);let tiny=Budget::new(4096).unwrap();assert!(matches!(generate_from_pages(&pages,&HashMap::new(),&tiny,&||if tiny.denied(){Err(io::ErrorKind::Interrupted.into())}else{Ok(())}),Err(Failure::Operational(ref error))if error.kind()==io::ErrorKind::OutOfMemory));assert!(!generate_from_pages(&pages,&HashMap::new(),&Budget::new(16*1024*1024).unwrap(),&||Ok(())).unwrap().body.is_empty());}
#[test]fn actions_pages_ignore_only_exact_own_generated_notice_membership(){let root=std::env::current_dir().unwrap().join("actions-page-own");let pages=Pages{files:[("code/a.dm","ACTION(hit, num/power)\n"),("code/engine/_generated/actions.dm","/datum/notice/hit/var/power\n")].into_iter().map(|(rel,text)|File::capture(&root,&root.join(rel),text.to_owned().into()).unwrap()).collect(),fail:Cell::new(false),stop:Cell::new(false)};let output=generate_from_pages(&pages,&HashMap::new(),&Budget::new(16*1024*1024).unwrap(),&||Ok(())).unwrap();assert!(output.body.contains("/datum/notice/hit\n\tvar/num/power"));}
}
